package resolvers

import (
	"context"
	"strconv"

	"doublets-gql/generated"
)

// From resolves the from field of a Links object
// This would be generated by gqlgen to handle the relationship
func (r *linksResolver) From(ctx context.Context, obj *generated.Links) (*generated.Links, error) {
	fromID, err := strconv.ParseUint(obj.FromID, 10, 64)
	if err != nil {
		return nil, err
	}
	
	link, err := r.store.Get(ctx, fromID)
	if err != nil {
		// If the link doesn't exist, return nil (GraphQL nullable field)
		return nil, nil
	}
	
	return &generated.Links{
		ID:     strconv.FormatUint(link.ID, 10),
		FromID: strconv.FormatUint(link.FromID, 10),
		ToID:   strconv.FormatUint(link.ToID, 10),
	}, nil
}

