// Out resolves the out field of a Links object (outgoing relationships)
func (r *linksResolver) Out(ctx context.Context, obj *generated.Links, where *generated.LinksWhereInput, distinctOn []generated.LinksSelectColumn, orderBy []*generated.LinksOrderBy, offset *int, limit *int) ([]*generated.Links, error) {
	linkID, err := strconv.ParseUint(obj.ID, 10, 64)
	if err != nil {
		return nil, err
	}
	
	// Convert GraphQL input to store filter
	filter := convertWhereInput(where)
	
	if offset != nil {
		filter.Offset = offset
	}
	if limit != nil {
		filter.Limit = limit
	}
	
	// Convert order by
	if orderBy != nil {
		filter.OrderBy = convertOrderBy(orderBy)
	}
	
	// Get outgoing links
	links, err := r.store.GetOutgoing(ctx, linkID, filter)
	if err != nil {
		return nil, err
	}
	
	// Convert to GraphQL types
	result := make([]*generated.Links, len(links))
	for i, link := range links {
		result[i] = &generated.Links{
			ID:     strconv.FormatUint(link.ID, 10),
			FromID: strconv.FormatUint(link.FromID, 10),
			ToID:   strconv.FormatUint(link.ToID, 10),
		}
	}
	
	return result, nil
}

